import React from "react";
import Footer from "./Footer";
import Card from "./Card";
import Navbar from "./Navbar";

function Shop({ items, onBuy, purchasedItems }) {
  return (
    <>
      <Navbar />
      <div className="Body">
        {items.length === 0 ? (
          <p>No books available yet. Be the first to list one!</p>
        ) : (
          items.map((item) => (
            <Card key={item.id} pic={item.pic} title={item.title} para={item.para} price={item.price}>
              <button
                onClick={() => onBuy(item)}
                disabled={!!purchasedItems[item.id]}
                style={{
                  backgroundColor: purchasedItems[item.id] ? "grey" : "rgba(13, 110, 264, 1)",
                  color: "#fff",
                  borderRadius: "5px",
                  padding: "5px",
                  fontWeight: "100",
                  fontFamily: "Century Gothic",
                  width: "130px",
                }}
              >

                {purchasedItems[item.id] ? "Sold" : "Add to Cart"}

              </button>

            </Card>

          ))

        )}

      </div>

      <Footer />

    </>

  );

}



export default Shop;
